using System.Data;
using System.Windows;
using System.Windows.Controls;
namespace Hisab;
public sealed partial class MainWindow
{
    ReportSnapshot CaptureDisplayedReport(ReportSnapshot basis,DataGrid grid)
    {
        var headers=grid.Columns.OrderBy(c=>c.DisplayIndex).Select(c=>c.Header.ToString()!).ToArray();
        return basis with{Headers=headers,Rows=grid.Items.OfType<DataRowView>().Select(r=>headers.Select(h=>r[h]?.ToString()??"").ToArray()).ToArray()};
    }
    string NoncashLabel(string key)=>key switch{"AssetAcquisition"=>T("اقتناء أصل دون نقد","Noncash asset acquisition"),"DebtToEquity"=>T("تحويل دين إلى حقوق ملكية","Debt converted to equity"),_=>T("استثمار / تمويل غير نقدي آخر","Other noncash investing / financing")};
    DataTable NoncashData(DateTime from,DateTime to)
    {
        var data=new DataTable();foreach(string h in new[]{T("التاريخ / المستند","Date / document"),T("التصنيف","Category"),T("حساب الأصل المدين","Original debit account"),T("حساب الأصل الدائن","Original credit account"),T("المبلغ JOD","Amount JOD"),T("التفسير","Explanation"),T("الحالة","Status")})data.Columns.Add(h);
        foreach(var r in A.NoncashDisclosures(from,to))data.Rows.Add(r.Date+" · "+r.Number,NoncashLabel(r.Category),S.LocalName("accounts",r.DebitAccount,vm.Arabic),S.LocalName("accounts",r.CreditAccount,vm.Arabic),Store.Money(r.Amount),r.Note,r.Stale?T("تغير القيد — راجع الإفصاح","Journal changed — review disclosure"):T("مسجل صراحةً","Explicitly recorded"));return data;
    }
    void NoncashDisclosureForm()
    {
        S.Require("master");var(w,p,finish)=Dialog(T("إفصاح غير نقدي","Noncash disclosure"),1050,false);
        p.Children.Add(Text(T("سجّل الجزء غير النقدي فقط من نشاط استثماري أو تمويلي، واربطه بحسابي القيد الأصلي. هذا سجل إفصاحات يدوية وليس كشفًا تلقائيًا مكتملًا. للحذف اختر نفس الحسابات والتصنيف وأدخل صفرًا مع السبب.","Record only the noncash portion of an investing or financing activity, linked to the original journal accounts. This is an explicit disclosure register, not an automatically complete detection report. To remove an entry, select the same accounts/category and enter zero with a reason."),16));
        var documents=new ComboBox{DisplayMemberPath="Label",SelectedValuePath="Key",ItemsSource=A.NoncashDocuments().Rows.Cast<DataRow>().Select(r=>new Choice(r["id"].ToString()!,r["date"]+" · "+r["number"])).ToList()};var debit=new ComboBox{DisplayMemberPath="Label",SelectedValuePath="Key"};var credit=new ComboBox{DisplayMemberPath="Label",SelectedValuePath="Key"};var category=new ComboBox{DisplayMemberPath="Label",SelectedValuePath="Key",ItemsSource=AccountingService.NoncashCategories.Select(k=>new Choice(k,NoncashLabel(k))).ToList(),SelectedIndex=0};var amount=new TextBox{Text="0.000"};var note=new TextBox();
        void LoadSaved(){if(long.TryParse(documents.SelectedValue?.ToString(),out long doc)&&long.TryParse(debit.SelectedValue?.ToString(),out long dr)&&long.TryParse(credit.SelectedValue?.ToString(),out long cr)&&category.SelectedValue is string cat){var existing=S.Table("SELECT amount,note FROM noncash_disclosures WHERE doc=@p0 AND debit_account=@p1 AND credit_account=@p2 AND category=@p3",doc,dr,cr,cat);amount.Text=existing.Rows.Count==0?"0.000":Store.Money((long)existing.Rows[0]["amount"]);note.Text=existing.Rows.Count==0?"":(string)existing.Rows[0]["note"];}}
        documents.SelectionChanged+=(s,e)=>{if(!long.TryParse(documents.SelectedValue?.ToString(),out long id))return;List<Choice> Choices(bool side)=>A.NoncashAccounts(id,side).Rows.Cast<DataRow>().Select(r=>new Choice(r["id"].ToString()!,r["code"]+" · "+S.LocalName("accounts",(long)r["id"],vm.Arabic)+" · "+Store.Money((long)r["amount"]))).ToList();debit.ItemsSource=Choices(true);credit.ItemsSource=Choices(false);debit.SelectedIndex=0;credit.SelectedIndex=0;LoadSaved();};debit.SelectionChanged+=(s,e)=>LoadSaved();credit.SelectionChanged+=(s,e)=>LoadSaved();category.SelectionChanged+=(s,e)=>LoadSaved();
        p.Children.Add(Field(T("المستند","Document"),documents));p.Children.Add(Field(T("الحساب المدين","Debit account"),debit));p.Children.Add(Field(T("الحساب الدائن","Credit account"),credit));p.Children.Add(Field(T("التصنيف","Category"),category));p.Children.Add(Field(T("المبلغ JOD","Amount JOD"),amount));p.Children.Add(Field(T("التفسير / سبب التصحيح","Explanation / correction reason"),note));
        p.Children.Add(Actions(Btn(T("عرض المستند","View document"),()=>{if(long.TryParse(documents.SelectedValue?.ToString(),out long id))ShowDocument(id);}),Btn(T("حفظ","Save"),()=>{if(!long.TryParse(documents.SelectedValue?.ToString(),out long id)||!long.TryParse(debit.SelectedValue?.ToString(),out long dr)||!long.TryParse(credit.SelectedValue?.ToString(),out long cr)||category.SelectedValue is not string cat)throw new InvalidOperationException(T("أكمل الاختيارات","Complete the selections"));A.SaveNoncashDisclosure(id,dr,cr,cat,Store.Parse(amount.Text),note.Text);LoadSaved();vm.Status=T("حُفظ الإفصاح","Disclosure saved");},true)));if(documents.Items.Count>0)documents.SelectedIndex=0;w.ShowDialog();
    }
    void SavedReportSnapshots()
    {
        var(w,p,finish)=Dialog(T("نسخ التقارير المحفوظة","Saved report snapshots"),1100,false);
        var picker=new ComboBox{DisplayMemberPath="Label",SelectedValuePath="Key",ItemsSource=S.ReportSnapshots().Rows.Cast<DataRow>().Select(r=>new Choice(r["id"].ToString()!,"#"+r["id"]+" · "+r["title"]+" · "+r["created"]+" · "+r["username"])).ToList()};var content=new StackPanel();ReportSnapshot? selected=null;
        picker.SelectionChanged+=(s,e)=>{if(!long.TryParse(picker.SelectedValue?.ToString(),out long id))return;selected=S.LoadReportSnapshot(id);content.Children.Clear();content.FlowDirection=selected.Language=="ar"?FlowDirection.RightToLeft:FlowDirection.LeftToRight;content.Children.Add(Text(selected.Company+" · "+selected.Title,20,true));content.Children.Add(Text(selected.Note,16));var data=selected.ToTable();var grid=Grid(data,data.Columns.Cast<DataColumn>().Select(c=>(c.ColumnName,c.ColumnName,c.Ordinal==0?2.0:1.0)).ToArray());grid.CanUserSortColumns=false;grid.CanUserReorderColumns=false;grid.MaxHeight=350;grid.RowHeight=double.NaN;foreach(var col in grid.Columns.OfType<DataGridTextColumn>()){col.MinWidth=150;var style=new Style(typeof(TextBlock),col.ElementStyle);style.Setters.Add(new Setter(TextBlock.TextWrappingProperty,TextWrapping.Wrap));style.Setters.Add(new Setter(TextBlock.TextTrimmingProperty,TextTrimming.None));col.ElementStyle=style;}content.Children.Add(grid);};
        p.Children.Add(Text(T("نسخة ثابتة من التقرير المعروض وقت الحفظ، وليست إعادة احتساب للأرصدة الحالية. لا تعدّل النسخ المحفوظة؛ احفظ نسخة جديدة للتصحيح.","A fixed copy of the report as displayed when saved, not a recalculation of current balances. Saved copies cannot be edited; save a new copy for corrections."),16));p.Children.Add(Field(T("النسخة","Snapshot"),picker));p.Children.Add(content);
        p.Children.Add(Actions(Btn(T("طباعة / PDF","Print / PDF"),()=>{if(selected!=null)Print(ReportDocument(selected.Title,selected.ToTable(),selected.Note,selected.Company,selected.Language));}),Btn(T("تصدير CSV","Export CSV"),()=>{if(selected!=null)Export(selected.ToTable(),selected);}),Btn(T("إغلاق","Close"),finish)));if(picker.Items.Count>0)picker.SelectedIndex=0;else content.Children.Add(Text(T("لا توجد نسخ محفوظة","No saved snapshots"),16));w.ShowDialog();
    }
}
